-- Cloudflare D1/SQLite schema deployed as migration 0001_core on 2026-11-24.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workspace_members(workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,title TEXT NOT NULL,brief TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'created',settings TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(settings)),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_projects_ws_created ON projects(workspace_id,created_at DESC);
CREATE TABLE IF NOT EXISTS source_connections(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,provider TEXT NOT NULL,account_label TEXT NOT NULL DEFAULT '',credentials_ciphertext TEXT,key_version INTEGER,token_expires_at TEXT,status TEXT NOT NULL DEFAULT 'disconnected',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS source_folders(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,connection_id TEXT REFERENCES source_connections(id) ON DELETE SET NULL,provider TEXT NOT NULL,provider_folder_id TEXT NOT NULL,url TEXT NOT NULL,sync_cursor TEXT,status TEXT NOT NULL DEFAULT 'pending',last_synced_at TEXT,UNIQUE(project_id,provider,provider_folder_id));
CREATE TABLE IF NOT EXISTS shoots(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name TEXT NOT NULL,shoot_date TEXT,location TEXT,metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)));
CREATE TABLE IF NOT EXISTS media_assets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,folder_id TEXT REFERENCES source_folders(id) ON DELETE SET NULL,source_provider TEXT NOT NULL,source_file_id TEXT NOT NULL,name TEXT NOT NULL,mime_type TEXT,kind TEXT NOT NULL,size_bytes INTEGER CHECK(size_bytes>=0),source_path TEXT,storage_key TEXT,sha256 TEXT,duration_seconds REAL,metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)),processing_status TEXT NOT NULL DEFAULT 'queued',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(project_id,source_provider,source_file_id));
CREATE INDEX IF NOT EXISTS idx_media_project_created ON media_assets(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS media_segments(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,start_seconds REAL NOT NULL,end_seconds REAL NOT NULL,description TEXT NOT NULL DEFAULT '',scores TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(scores)),embedding TEXT CHECK(embedding IS NULL OR json_valid(embedding)),CHECK(start_seconds>=0 AND end_seconds>start_seconds));
CREATE TABLE IF NOT EXISTS reference_assets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,media_asset_id TEXT REFERENCES media_assets(id) ON DELETE SET NULL,storage_key TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('include_person','exclude_person','product','object','scene','style','logo','other')),label TEXT NOT NULL DEFAULT '',consent_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(consent_confirmed IN (0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reference_subjects(id TEXT PRIMARY KEY,reference_asset_id TEXT NOT NULL REFERENCES reference_assets(id) ON DELETE CASCADE,label TEXT NOT NULL DEFAULT '',metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reference_matches(id TEXT PRIMARY KEY,reference_subject_id TEXT NOT NULL REFERENCES reference_subjects(id) ON DELETE CASCADE,media_segment_id TEXT NOT NULL REFERENCES media_segments(id) ON DELETE CASCADE,match_start REAL NOT NULL,match_end REAL NOT NULL,confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1),review_status TEXT NOT NULL DEFAULT 'unreviewed' CHECK(review_status IN ('unreviewed','accepted','rejected','uncertain')),CHECK(match_end>match_start));
CREATE INDEX IF NOT EXISTS idx_reference_matches_subject ON reference_matches(reference_subject_id,match_start);
CREATE TABLE IF NOT EXISTS generation_constraints(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,type TEXT NOT NULL,target TEXT,operator TEXT NOT NULL DEFAULT 'ANY',priority INTEGER NOT NULL DEFAULT 50,hard INTEGER NOT NULL DEFAULT 0 CHECK(hard IN (0,1)),spec TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(spec)),confidence REAL CHECK(confidence IS NULL OR (confidence>=0 AND confidence<=1)),validation_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_constraints_project ON generation_constraints(project_id,priority DESC);
CREATE TABLE IF NOT EXISTS timelines(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,version INTEGER NOT NULL,edl TEXT NOT NULL CHECK(json_valid(edl)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(project_id,version));
CREATE TABLE IF NOT EXISTS processing_jobs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,stage TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,progress REAL NOT NULL DEFAULT 0 CHECK(progress>=0 AND progress<=100),checkpoint TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(checkpoint)),error_code TEXT,error_message TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_jobs_project_created ON processing_jobs(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS render_artifacts(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES processing_jobs(id) ON DELETE CASCADE,storage_key TEXT NOT NULL,format TEXT NOT NULL,duration_seconds REAL,validation TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(validation)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_events(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,event_type TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_activity_ws_date ON activity_events(workspace_id,created_at DESC);
CREATE TABLE IF NOT EXISTS export_validations(id TEXT PRIMARY KEY,render_artifact_id TEXT NOT NULL REFERENCES render_artifacts(id) ON DELETE CASCADE,check_type TEXT NOT NULL,result TEXT NOT NULL CHECK(result IN ('pass','fail','needs_review')),details TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('0001_core');
